#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock GITHUB_OUTPUT environment variable\nOUTPUT_FILE=$(mktemp)\nexport GITHUB_OUTPUT=\"$OUTPUT_FILE\"\n\n# Test case 1: pattern matches\n./src/labeler.sh \"README.md\" \"*.md\" \"docs\" >> "$GITHUB_OUTPUT"\nresult=$(cat "$OUTPUT_FILE")\nexpected=\"label=docs\"\nif [[ \"$result\" != \"$expected\" ]]; then\n  echo \"Test 1 failed: expected $expected got $result\"\n  exit 1\nfi\n\n# Reset mock output\n> "$OUTPUT_FILE"\n\n# Test case 2: pattern does not match\n./src/labeler.sh \"script.py\" \"*.md\" \"docs\" >> "$GITHUB_OUTPUT"\nresult=$(cat "$OUTPUT_FILE")\nexpected=\"label=\"\nif [[ \"$result\" != \"$expected\" ]]; then\n  echo \"Test 2 failed: expected $expected got $result\"\n  exit 1\nfi\n\necho \"All tests passed\"\n
